/bin/bash -lc "python - <<'PY'
import os
import signal
for entry in os.scandir('/proc'):
    if not entry.name.isdigit():
        continue
    try:
        with open(f'/proc/{entry.name}/cmdline', 'rb') as stream:
            args = stream.read().split(b'\\0')
        if len(args) >= 5 and args[1:4] == [b'-m', b'pytest', b'-q'] and b'addopts=' in args:
            os.kill(int(entry.name), signal.SIGINT)
            print('Interrupted full pytest run after repeated end-to-end errors')
    except (FileNotFoundError, ProcessLookupError, PermissionError):
        pass
